import { listRows } from './query.mjs';
export function reportHandler(request, db) {
  return { status: 200, body: listRows(db, request.tenantId) };
}

files.src/reporting/query.mjs:
export function listRows(db, tenantId) {
  if (!tenantId) throw new Error('tenantId required');
  return db.rows.filter(row => row.tenantId === tenantId)
    .sort((a, b) => a.id.localeCompare(b.id)).slice(0, 500);
}

