export async function deleteKey(store, key) { return store.remove(key); }
export async function deletePrefix(store, prefix) {
  for (const file of await store.list(prefix)) await store.remove(file.key);
}

files.src/reporting/complete.mjs:
export async function complete(db, reportId) {
  return db.insertCompletionOnce(reportId);
}

files.src/reporting/list.mjs:
export function list(request, db) {
  const size = Number(request.query.size ?? 50);
  if (size > 50) return { status: 400 };
  return { status: 200, body: db.rows.filter(row => row.tenantId === request.tenantId).slice(0, size) };
}
export const aliases = ['/reports', '/report-list'];

